CREATE TABLE `weapon_skill` (
  `weapon_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `note` varchar(255) DEFAULT NULL,
  `skill_name` varchar(45) DEFAULT NULL,
  `probability` int(3) unsigned NOT NULL DEFAULT '0',
  `prob_every_enchant` int(2) NOT NULL DEFAULT '0' COMMENT '使用武卷成功+n，魔法發動機率也會+n%',
  `base_damage` int(10) unsigned NOT NULL DEFAULT '0',
  `random_damage` int(10) unsigned NOT NULL DEFAULT '0',
  `area` int(6) NOT NULL DEFAULT '0',
  `effect_id` int(6) unsigned NOT NULL DEFAULT '0',
  `is_target_effect` int(1) unsigned NOT NULL DEFAULT '0',
  `is_arrow` int(1) unsigned NOT NULL DEFAULT '0',
  `attr` int(3) NOT NULL DEFAULT '0',
  `berserkers_rate` double(5,2) NOT NULL DEFAULT '1.20' COMMENT '狂暴術加成倍率',
  `leech_hp` int(5) NOT NULL DEFAULT '0' COMMENT '吸血',
  `leech_mp` int(5) NOT NULL DEFAULT '0' COMMENT '吸魔',
  `leech_every_enchant` int(2) NOT NULL DEFAULT '0' COMMENT '武器每+n 多吸n滴血/魔',
  `chaser_attack_gfxid` int(5) NOT NULL DEFAULT '0' COMMENT '底比斯武器的特效編號',
  `is_caotic` int(1) NOT NULL DEFAULT '0' COMMENT '邪惡值越高，攻擊力越強',
  `is_skill_freeze` int(1) NOT NULL DEFAULT '0' COMMENT '是否凍結目標',
  `is_skill_disease` int(1) NOT NULL DEFAULT '0' COMMENT '是否疾病術目標',
  `is_skill_bind` int(1) NOT NULL DEFAULT '0' COMMENT '是否束縛目標',
  `is_skill_turn_undead` int(1) NOT NULL DEFAULT '0' COMMENT '是否起死回生目標',
  `is_skill_mind_break` int(1) NOT NULL DEFAULT '0' COMMENT '心靈破壞',
  PRIMARY KEY (`weapon_id`)
) ENGINE=MyISAM AUTO_INCREMENT=100206 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of weapon_skill
-- ----------------------------

